//! Zero-cost schema markers: tables, columns, and their relational contracts.
//!
//! Tables and columns are represented as zero-sized types. Every column is
//! statically tied to its owning table through [`Column::Table`], which lets the
//! compiler reject expressions that mix columns from unrelated tables at the
//! call site.

use core::marker::PhantomData;

use crate::dialect::Dialect;
use crate::expr::Unscoped;

/// A table of the database schema, represented as a zero-sized marker type.
///
/// Implementations are usually generated by the [`table!`](crate::table) macro.
pub trait Table {
    /// The SQL identifier of the table, known at compile time.
    const NAME: &'static str;

    /// The `FROM` / `JOIN` reference of this table, alias included.
    ///
    /// The default reference is the bare table name; [`Aliased`] tables override
    /// it to render their `AS` clause.
    fn table_ref() -> TableRef {
        TableRef::plain(Self::NAME)
    }

    /// Builds the expression node referencing `column` of this table.
    ///
    /// The default carries the SQL name of the table, which lets the renderer
    /// qualify the reference whenever the statement spans several relations;
    /// tables referenced under an alias override it to carry their alias, so
    /// joins over repeated table references stay unambiguous.
    fn column_expr(column: &'static str) -> crate::expr::ExprKind {
        crate::expr::ExprKind::Column {
            table: Self::NAME,
            name: column,
        }
    }
}

/// A table reference rendered into a `FROM` or `JOIN` clause.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub struct TableRef {
    /// The SQL identifier of the table.
    pub name: &'static str,

    /// The optional alias the table is referenced by.
    pub alias: Option<&'static str>,
}

impl TableRef {
    /// Creates a reference to a table without an alias.
    pub const fn plain(name: &'static str) -> Self {
        Self { name, alias: None }
    }

    /// Creates a reference to `name` exposed under `alias`.
    pub const fn aliased(name: &'static str, alias: &'static str) -> Self {
        Self {
            name,
            alias: Some(alias),
        }
    }

    /// Renders the reference, appending `AS "alias"` when the table is aliased.
    pub fn render<D: Dialect>(&self, out: &mut String) {
        D::push_quoted_identifier(out, self.name);
        if let Some(alias) = self.alias {
            out.push_str(" AS ");
            D::push_quoted_identifier(out, alias);
        }
    }
}

/// A column of a database [`Table`], represented as a zero-sized marker type.
pub trait Column {
    /// The table this column belongs to.
    type Table: Table;

    /// The Rust type used to represent this column's values.
    type RustType;

    /// The SQL identifier of the column, known at compile time.
    const NAME: &'static str;

    /// Builds the expression node referencing this column.
    ///
    /// The node carries the [`Table::NAME`] of [`Column::Table`], so the renderer
    /// qualifies the reference whenever a bare name would be ambiguous or
    /// unresolvable; columns of an [`Aliased`] table override it to reference
    /// their alias directly.
    fn expr_kind() -> crate::expr::ExprKind {
        crate::expr::ExprKind::Column {
            table: <Self::Table as Table>::NAME,
            name: Self::NAME,
        }
    }

    /// Addresses this column through the table alias `A`.
    ///
    /// Column markers are zero-sized values, so the method only fixes the alias
    /// the column is referenced by and returns the matching [`AliasedCol`]
    /// marker without any turbofish-heavy construction:
    ///
    /// ```
    /// use rurqe_core::schema::{AliasedCol, Column, TableAlias};
    ///
    /// rurqe_core::table! {
    ///     User => "users" {
    ///         UserId => "id": i64,
    ///     }
    /// }
    ///
    /// rurqe_core::table_alias! {
    ///     /// The `u` alias.
    ///     U1 => "u"
    /// }
    ///
    /// let through_column: AliasedCol<U1, UserId> = UserId.alias::<U1>();
    /// let through_alias: AliasedCol<U1, UserId> = U1.col(UserId);
    /// ```
    fn alias<A: TableAlias>(self) -> AliasedCol<A, Self>
    where
        Self: Sized,
    {
        AliasedCol::new()
    }
}

/// Statically asserts that a [`Column`] belongs to the table `T`.
///
/// The trait is satisfied exactly for the table declared as
/// [`Column::Table`], so using a column with a foreign table fails to compile
/// with a short, actionable diagnostic.
#[diagnostic::on_unimplemented(
    message = "column `{Self}` does not belong to table `{T}`",
    label = "column `{Self}` cannot be used where a column of `{T}` is required",
    note = "a column may only be used with the table declared by its `Column::Table` associated type"
)]
pub trait ColumnBelongsTo<T: Table> {}

impl<C: Column> ColumnBelongsTo<C::Table> for C {}

/// A compile-time name under which an [`Aliased`] table is referenced.
///
/// Aliases are declared with the [`table_alias!`](crate::table_alias) macro:
///
/// ```
/// rurqe_core::table_alias! {
///     /// The `u` alias.
///     UserAlias => "u"
/// }
///
/// use rurqe_core::schema::TableAlias;
///
/// assert_eq!(UserAlias::NAME, "u");
/// ```
pub trait TableAlias: Sized {
    /// The SQL identifier of the alias, known at compile time.
    const NAME: &'static str;

    /// Renders `table` under this alias, as used in `FROM` and `JOIN` clauses.
    fn table_ref(table: &'static str) -> TableRef {
        TableRef::aliased(table, Self::NAME)
    }

    /// Builds the expression node referencing `column` of a table through this alias.
    fn column_expr(column: &'static str) -> crate::expr::ExprKind {
        crate::expr::ExprKind::QualifiedColumn {
            table: Self::NAME,
            column,
        }
    }

    /// Addresses the column `C` through this alias.
    ///
    /// Alias markers are zero-sized values, so the method only fixes the column
    /// referenced through the alias and returns the matching [`AliasedCol`]
    /// marker:
    ///
    /// ```
    /// use rurqe_core::schema::{AliasedCol, Column, TableAlias};
    ///
    /// rurqe_core::table! {
    ///     User => "users" {
    ///         UserId => "id": i64,
    ///     }
    /// }
    ///
    /// rurqe_core::table_alias! {
    ///     /// The `u` alias.
    ///     U1 => "u"
    /// }
    ///
    /// let aliased: AliasedCol<U1, UserId> = U1.col(UserId);
    /// let through_column: AliasedCol<U1, UserId> = UserId.alias::<U1>();
    /// ```
    fn col<C: Column>(self, _column: C) -> AliasedCol<Self, C> {
        AliasedCol::new()
    }
}

/// Declares a table alias marker type together with its SQL name.
///
/// ```
/// rurqe_core::table_alias! {
///     /// The `o` alias.
///     OrderAlias => "o"
/// }
///
/// use rurqe_core::schema::TableAlias;
///
/// assert_eq!(OrderAlias::NAME, "o");
/// ```
#[macro_export]
macro_rules! table_alias {
    (
        $(#[$alias_meta:meta])*
        $alias:ident => $alias_name:literal
    ) => {
        $(#[$alias_meta])*
        #[allow(dead_code)]
        #[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
        pub struct $alias;

        impl $crate::schema::TableAlias for $alias {
            const NAME: &'static str = $alias_name;
        }
    };
}

/// The table `T` referenced under the alias `A`.
///
/// The marker keeps the schema identity of `T` — so its columns still belong to
/// `T` — while rendering `"table" AS "alias"` in `FROM` and `JOIN` clauses.
///
/// ```text
/// SELECT "u"."id" FROM "users" AS "u"
/// ```
pub struct Aliased<T, A>(PhantomData<fn() -> (T, A)>);

impl<T: Table, A: TableAlias> Table for Aliased<T, A> {
    const NAME: &'static str = T::NAME;

    fn table_ref() -> TableRef {
        TableRef::aliased(T::NAME, A::NAME)
    }

    fn column_expr(column: &'static str) -> crate::expr::ExprKind {
        crate::expr::ExprKind::QualifiedColumn {
            table: A::NAME,
            column,
        }
    }
}

/// The column `C` referenced through the table alias `A`.
///
/// The column keeps its Rust type and owning table, while its SQL reference
/// becomes `"alias"."column"`, which keeps self-joins and repeated table
/// references unambiguous.
pub struct AliasedCol<A, C>(PhantomData<fn() -> (A, C)>);

impl<A: TableAlias, C: Column> AliasedCol<A, C> {
    /// Creates the aliased column marker for the column `C` under the alias `A`.
    pub fn new() -> Self {
        AliasedCol(PhantomData)
    }
}

impl<A: TableAlias, C: Column> Default for AliasedCol<A, C> {
    fn default() -> Self {
        Self::new()
    }
}

impl<A: TableAlias, C: Column> Column for AliasedCol<A, C> {
    type Table = Aliased<C::Table, A>;
    type RustType = C::RustType;

    const NAME: &'static str = C::NAME;

    fn expr_kind() -> crate::expr::ExprKind {
        crate::expr::ExprKind::QualifiedColumn {
            table: A::NAME,
            column: C::NAME,
        }
    }
}

// An aliased column keeps the Rust type of the column it addresses, so it takes
// part in arithmetic exactly like the plain marker does, and its expression
// stays qualified by the alias. The helper generating those operators is
// declared further down, so its invocation is placed right after the definition.

/// Position marker used to disambiguate table membership in composite scopes.
///
/// Lone tables use position 0 ([`At<0>`]), while composite scopes such as `(T1, T2)`
/// assign positions `At<1>`, `At<2>`, etc. to each member.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub struct At<const N: usize>;

/// A position marker nested one level deeper than `P`.
///
/// Joined query scopes such as [`Joined`](crate::query::Joined) wrap the
/// positions of their inner scope in `Next`, so a table stays reachable exactly
/// once per scope without const-generic arithmetic.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub struct Next<P>(core::marker::PhantomData<P>);

/// Statically asserts that the [`Table`] `T` is part of the query scope.
///
/// Expressions may only reference tables that were added to the query, and every
/// table is trivially in scope of itself. Composite scopes represented as tuples
/// contain each of their member tables at distinct positions.
///
/// ```compile_fail
/// use rurqe_core::schema::{Table, TableInScope};
///
/// rurqe_core::table! {
///     User => "users" { UserId => "id": i64, }
/// }
///
/// rurqe_core::table! {
///     Order => "orders" { OrderId => "id": i64, }
/// }
///
/// fn require_in_scope<T: Table, S: TableInScope<T, P>, P>() {}
///
/// // Fails to compile because `Order` is not in scope of `User`:
/// require_in_scope::<Order, User, _>();
/// ```
#[diagnostic::on_unimplemented(
    message = "table `{T}` is not part of this query's scope",
    label = "add `{T}` to the query before referencing its columns",
    note = "only tables introduced into the query scope can be used by its expressions"
)]
pub trait TableInScope<T: Table, P = At<0>> {}

impl<T: Table> TableInScope<T, At<0>> for T {}

macro_rules! impl_tuple_scope {
    ($(($elem:ident, $pos:expr) in ($($member:ident),+);)+) => {
        $(
            impl<$($member: Table),+> TableInScope<$elem, At<$pos>> for ($($member,)+) {}
        )+
    };
}

impl_tuple_scope! {
    (T1, 1) in (T1);

    (T1, 1) in (T1, T2);
    (T2, 2) in (T1, T2);

    (T1, 1) in (T1, T2, T3);
    (T2, 2) in (T1, T2, T3);
    (T3, 3) in (T1, T2, T3);

    (T1, 1) in (T1, T2, T3, T4);
    (T2, 2) in (T1, T2, T3, T4);
    (T3, 3) in (T1, T2, T3, T4);
    (T4, 4) in (T1, T2, T3, T4);

    (T1, 1) in (T1, T2, T3, T4, T5);
    (T2, 2) in (T1, T2, T3, T4, T5);
    (T3, 3) in (T1, T2, T3, T4, T5);
    (T4, 4) in (T1, T2, T3, T4, T5);
    (T5, 5) in (T1, T2, T3, T4, T5);

    (T1, 1) in (T1, T2, T3, T4, T5, T6);
    (T2, 2) in (T1, T2, T3, T4, T5, T6);
    (T3, 3) in (T1, T2, T3, T4, T5, T6);
    (T4, 4) in (T1, T2, T3, T4, T5, T6);
    (T5, 5) in (T1, T2, T3, T4, T5, T6);
    (T6, 6) in (T1, T2, T3, T4, T5, T6);

    (T1, 1) in (T1, T2, T3, T4, T5, T6, T7);
    (T2, 2) in (T1, T2, T3, T4, T5, T6, T7);
    (T3, 3) in (T1, T2, T3, T4, T5, T6, T7);
    (T4, 4) in (T1, T2, T3, T4, T5, T6, T7);
    (T5, 5) in (T1, T2, T3, T4, T5, T6, T7);
    (T6, 6) in (T1, T2, T3, T4, T5, T6, T7);
    (T7, 7) in (T1, T2, T3, T4, T5, T6, T7);

    (T1, 1) in (T1, T2, T3, T4, T5, T6, T7, T8);
    (T2, 2) in (T1, T2, T3, T4, T5, T6, T7, T8);
    (T3, 3) in (T1, T2, T3, T4, T5, T6, T7, T8);
    (T4, 4) in (T1, T2, T3, T4, T5, T6, T7, T8);
    (T5, 5) in (T1, T2, T3, T4, T5, T6, T7, T8);
    (T6, 6) in (T1, T2, T3, T4, T5, T6, T7, T8);
    (T7, 7) in (T1, T2, T3, T4, T5, T6, T7, T8);
    (T8, 8) in (T1, T2, T3, T4, T5, T6, T7, T8);
}

/// Statically asserts that `T` denotes a valid expression scope.
///
/// A scope is the set of relations an expression may reference: a lone table
/// ([`Table`]), a tuple of tables, or a joined query scope such as
/// [`Joined`](crate::query::Joined) and
/// [`LeftJoined`](crate::query::LeftJoined). The marker keeps expression
/// builders honest across joins without pinning them to one concrete scope
/// representation.
#[diagnostic::on_unimplemented(
    message = "`{Self}` is not a valid expression scope",
    label = "expressions may only reference tables, table tuples, or joined scopes",
    note = "build expressions against a table, a tuple of tables, or a `Joined` / `LeftJoined` scope"
)]
pub trait ExprScope {}

impl<T: Table> ExprScope for T {}

macro_rules! impl_tuple_expr_scope {
    ($($member:ident),+) => {
        impl<$($member: Table),+> ExprScope for ($($member,)+) {}
    };
}

impl_tuple_expr_scope!(T1);

impl_tuple_expr_scope!(T1, T2);

impl_tuple_expr_scope!(T1, T2, T3);

impl_tuple_expr_scope!(T1, T2, T3, T4);

impl_tuple_expr_scope!(T1, T2, T3, T4, T5);

impl_tuple_expr_scope!(T1, T2, T3, T4, T5, T6);

impl_tuple_expr_scope!(T1, T2, T3, T4, T5, T6, T7);

impl_tuple_expr_scope!(T1, T2, T3, T4, T5, T6, T7, T8);

/// Statically asserts that every table an expression references is part of the
/// query scope.
///
/// The scope of an expression is the set of tables its columns belong to, which
/// [`Expr`](crate::expr::Expr) carries as its scope parameter. A reference to a
/// single column yields the bare [`Table`], a reference spanning several tables
/// yields a tuple of tables, and an expression referencing no table at all
/// carries `()`. Bounding the scope by `ExprInScope<Tables, _>` therefore
/// rejects a reference to a table that was never added to the query at the call
/// site.
///
/// ```compile_fail
/// use rurqe_core::schema::{ExprInScope, Table, TableInScope};
///
/// rurqe_core::table! {
///     User => "users" { UserId => "id": i64, }
/// }
///
/// rurqe_core::table! {
///     Order => "orders" { OrderId => "id": i64, }
/// }
///
/// fn require_in_scope<S, Tables, P>()
/// where
///     S: ExprInScope<Tables, P>,
/// {
/// }
///
/// // Fails to compile because `Order` is not part of the `users` scope:
/// require_in_scope::<Order, User, _>();
/// ```
#[diagnostic::on_unimplemented(
    message = "expression references table `{Self}`, which is not part of this query's scope",
    label = "table `{Self}` is not in scope for this query",
    note = "add `{Self}` to the query via `from`, `inner_join`, or `left_join` before referencing its columns"
)]
pub trait ExprInScope<Tables, Positions = At<0>> {}

impl<Tables, Positions> ExprInScope<Tables, Positions> for () {}

// An expression whose scope was dropped declares that its tables are checked by
// the statement enclosing it, so it is accepted in every scope — while staying
// distinguishable from an expression that references no table at all.
impl<Tables, Positions> ExprInScope<Tables, Positions> for Unscoped {}

impl<T: Table, Tables, P> ExprInScope<Tables, P> for T where Tables: TableInScope<T, P> {}

macro_rules! impl_tuple_expr_in_scope {
    ($($member:ident : $pos:ident),+) => {
        impl<$($member: Table),+, Tables, $($pos),+> ExprInScope<Tables, ($($pos,)+)>
            for ($($member,)+)
        where
            $(Tables: TableInScope<$member, $pos>),+
        {
        }
    };
}

impl_tuple_expr_in_scope!(T1: P1);

impl_tuple_expr_in_scope!(T1: P1, T2: P2);

impl_tuple_expr_in_scope!(T1: P1, T2: P2, T3: P3);

impl_tuple_expr_in_scope!(T1: P1, T2: P2, T3: P3, T4: P4);

impl_tuple_expr_in_scope!(T1: P1, T2: P2, T3: P3, T4: P4, T5: P5);

impl_tuple_expr_in_scope!(T1: P1, T2: P2, T3: P3, T4: P4, T5: P5, T6: P6);

impl_tuple_expr_in_scope!(T1: P1, T2: P2, T3: P3, T4: P4, T5: P5, T6: P6, T7: P7);

impl_tuple_expr_in_scope!(T1: P1, T2: P2, T3: P3, T4: P4, T5: P5, T6: P6, T7: P7, T8: P8);

/// Combines two expression scopes into the scope referencing both of them.
///
/// Joins extend the scope of a query by the tables they introduce, and an
/// expression built from columns of several tables carries the union of their
/// scopes. The trait names that union at the type level: `()` contributes
/// nothing, a single table contributes itself, and any further table extends a
/// tuple of references from the left.
///
/// ```
/// use rurqe_core::schema::CombineScope;
///
/// rurqe_core::table! {
///     User => "users" { UserId => "id": i64, }
/// }
///
/// rurqe_core::table! {
///     Order => "orders" { OrderId => "id": i64, }
/// }
///
/// fn assert_combined<A: CombineScope<B, Combined = C>, B, C>() {}
///
/// assert_combined::<User, Order, (User, Order)>();
/// assert_combined::<(User, Order), User, (User, Order, User)>();
/// ```
pub trait CombineScope<Other> {
    /// The scope referencing both `Self` and `Other`.
    type Combined;
}

impl CombineScope<()> for () {
    type Combined = ();
}

impl<T: Table> CombineScope<()> for T {
    type Combined = T;
}

impl<T: Table> CombineScope<T> for () {
    type Combined = T;
}

impl<T1: Table, T2: Table> CombineScope<T2> for T1 {
    type Combined = (T1, T2);
}

macro_rules! impl_tuple_combine_scope {
    ($($member:ident),+) => {
        impl<$($member: Table),+, Added: Table> CombineScope<Added> for ($($member,)+) {
            type Combined = ($($member,)+ Added);
        }
    };
}

impl_tuple_combine_scope!(T1);

impl_tuple_combine_scope!(T1, T2);

impl_tuple_combine_scope!(T1, T2, T3);

impl_tuple_combine_scope!(T1, T2, T3, T4);

impl_tuple_combine_scope!(T1, T2, T3, T4, T5);

impl_tuple_combine_scope!(T1, T2, T3, T4, T5, T6);

impl_tuple_combine_scope!(T1, T2, T3, T4, T5, T6, T7);

/// Trait for extending a relational scope with an additional table.
pub trait ExtendScope<S: Table> {
    /// The resulting composite scope after adding `S`.
    type Output;
}

impl<T: Table, S: Table> ExtendScope<S> for T {
    type Output = (T, S);
}

impl<T1: Table, S: Table> ExtendScope<S> for (T1,) {
    type Output = (T1, S);
}

impl<T1: Table, T2: Table, S: Table> ExtendScope<S> for (T1, T2) {
    type Output = (T1, T2, S);
}

impl<T1: Table, T2: Table, T3: Table, S: Table> ExtendScope<S> for (T1, T2, T3) {
    type Output = (T1, T2, T3, S);
}

impl<T1: Table, T2: Table, T3: Table, T4: Table, S: Table> ExtendScope<S> for (T1, T2, T3, T4) {
    type Output = (T1, T2, T3, T4, S);
}

impl<T1: Table, T2: Table, T3: Table, T4: Table, T5: Table, S: Table> ExtendScope<S>
    for (T1, T2, T3, T4, T5)
{
    type Output = (T1, T2, T3, T4, T5, S);
}

impl<T1: Table, T2: Table, T3: Table, T4: Table, T5: Table, T6: Table, S: Table> ExtendScope<S>
    for (T1, T2, T3, T4, T5, T6)
{
    type Output = (T1, T2, T3, T4, T5, T6, S);
}

impl<T1: Table, T2: Table, T3: Table, T4: Table, T5: Table, T6: Table, T7: Table, S: Table>
    ExtendScope<S> for (T1, T2, T3, T4, T5, T6, T7)
{
    type Output = (T1, T2, T3, T4, T5, T6, T7, S);
}

/// A value an arithmetic operator of a column marker combines with.
///
/// The trait is implemented for every operand the column's
/// [`RustType`](Column::RustType) accepts, so a column marker carries the
/// arithmetic operators exactly when its Rust type is a
/// [numeric](crate::expr::Numeric) type: `i32`, `i64`, `f64`, or an exact
/// [`rust_decimal::Decimal`].
#[diagnostic::on_unimplemented(
    message = "column `{C}` does not support SQL arithmetic with `{Self}`",
    label = "the column's Rust type is not numeric, or the value has another type",
    note = "arithmetic combines a numeric column with a value or an expression of the same Rust type"
)]
#[doc(hidden)]
pub trait ColumnArithmetic<C: Column> {
    /// The scope of the tables the operand references.
    type Scope;

    /// The aggregation marker the operand contributes.
    type Aggr;

    /// The dialect marker of the operand.
    type Dialect;

    /// Converts `self` into the expression node of the operand.
    fn into_operand_kind(self) -> crate::expr::ExprKind;
}

impl<C, V> ColumnArithmetic<C> for V
where
    C: Column,
    C::RustType: crate::expr::Numeric,
    V: crate::expr::NumericOperand<C::RustType>,
{
    type Scope = V::Scope;
    type Aggr = V::Aggr;
    type Dialect = V::Dialect;

    fn into_operand_kind(self) -> crate::expr::ExprKind {
        <V as crate::expr::NumericOperand<C::RustType>>::into_operand_kind(self)
    }
}

/// Assembles the binary expression node of a column arithmetic operator.
///
/// The node is built here instead of in the macro expansion, so the arithmetic
/// of a column marker keeps using the tree the expression builders use.
#[doc(hidden)]
pub fn arithmetic_kind(
    op: crate::expr::BinaryOp,
    lhs: crate::expr::ExprKind,
    rhs: crate::expr::ExprKind,
) -> crate::expr::ExprKind {
    crate::expr::ExprKind::Binary {
        op,
        lhs: Box::new(lhs),
        rhs: Box::new(rhs),
    }
}

/// Implements the arithmetic operators of [`Expr`](crate::expr::Expr) on a
/// column marker.
///
/// A column marker is a zero-sized value, so every operator builds the
/// expression of its column and yields the expression the matching operator of
/// [`Expr`](crate::expr::Expr) yields: the scopes of the operands merge, and a
/// column read per row keeps the result a per-row expression. The operators
/// exist exactly for the columns whose Rust type is numeric, because the
/// [operand](ColumnArithmetic) only has an implementation for such a type.
///
/// The two bracket groups carry the extra generics and the extra bounds of a
/// marker parameterised over a table alias, and stay empty for the markers
/// [`table!`] declares.
#[doc(hidden)]
#[macro_export]
macro_rules! __rurqe_column_arithmetic {
    (
        [$($extra_generics:tt)*]
        [$($extra_bounds:tt)*]
        $column:ty,
        $scope:ty $(,)?
    ) => {
        impl<Rhs $($extra_generics)*> ::core::ops::Add<Rhs> for $column
        where
            $($extra_bounds)*
            Rhs: $crate::schema::ColumnArithmetic<$column>,
            $scope: $crate::expr::MergeScope<Rhs::Scope>,
            $crate::expr::NonAggregate: $crate::expr::CombineAggr<Rhs::Aggr, Rhs::Scope>,
            (): $crate::expr::MergeDialect<Rhs::Dialect>,
        {
            type Output = $crate::expr::Expr<
                <$column as $crate::schema::Column>::RustType,
                $crate::expr::Merged<$scope, Rhs::Scope>,
                $crate::expr::CombinedAggr<$crate::expr::NonAggregate, Rhs::Aggr, Rhs::Scope>,
                $crate::expr::MergedDialect<(), Rhs::Dialect>,
            >;

            fn add(self, rhs: Rhs) -> Self::Output {
                $crate::expr::Expr::from_kind($crate::schema::arithmetic_kind(
                    $crate::expr::BinaryOp::Add,
                    <$column as $crate::schema::Column>::expr_kind(),
                    <Rhs as $crate::schema::ColumnArithmetic<$column>>::into_operand_kind(rhs),
                ))
            }
        }

        impl<Rhs $($extra_generics)*> ::core::ops::Sub<Rhs> for $column
        where
            $($extra_bounds)*
            Rhs: $crate::schema::ColumnArithmetic<$column>,
            $scope: $crate::expr::MergeScope<Rhs::Scope>,
            $crate::expr::NonAggregate: $crate::expr::CombineAggr<Rhs::Aggr, Rhs::Scope>,
            (): $crate::expr::MergeDialect<Rhs::Dialect>,
        {
            type Output = $crate::expr::Expr<
                <$column as $crate::schema::Column>::RustType,
                $crate::expr::Merged<$scope, Rhs::Scope>,
                $crate::expr::CombinedAggr<$crate::expr::NonAggregate, Rhs::Aggr, Rhs::Scope>,
                $crate::expr::MergedDialect<(), Rhs::Dialect>,
            >;

            fn sub(self, rhs: Rhs) -> Self::Output {
                $crate::expr::Expr::from_kind($crate::schema::arithmetic_kind(
                    $crate::expr::BinaryOp::Sub,
                    <$column as $crate::schema::Column>::expr_kind(),
                    <Rhs as $crate::schema::ColumnArithmetic<$column>>::into_operand_kind(rhs),
                ))
            }
        }

        impl<Rhs $($extra_generics)*> ::core::ops::Mul<Rhs> for $column
        where
            $($extra_bounds)*
            Rhs: $crate::schema::ColumnArithmetic<$column>,
            $scope: $crate::expr::MergeScope<Rhs::Scope>,
            $crate::expr::NonAggregate: $crate::expr::CombineAggr<Rhs::Aggr, Rhs::Scope>,
            (): $crate::expr::MergeDialect<Rhs::Dialect>,
        {
            type Output = $crate::expr::Expr<
                <$column as $crate::schema::Column>::RustType,
                $crate::expr::Merged<$scope, Rhs::Scope>,
                $crate::expr::CombinedAggr<$crate::expr::NonAggregate, Rhs::Aggr, Rhs::Scope>,
                $crate::expr::MergedDialect<(), Rhs::Dialect>,
            >;

            fn mul(self, rhs: Rhs) -> Self::Output {
                $crate::expr::Expr::from_kind($crate::schema::arithmetic_kind(
                    $crate::expr::BinaryOp::Mul,
                    <$column as $crate::schema::Column>::expr_kind(),
                    <Rhs as $crate::schema::ColumnArithmetic<$column>>::into_operand_kind(rhs),
                ))
            }
        }

        impl<Rhs $($extra_generics)*> ::core::ops::Div<Rhs> for $column
        where
            $($extra_bounds)*
            Rhs: $crate::schema::ColumnArithmetic<$column>,
            $scope: $crate::expr::MergeScope<Rhs::Scope>,
            $crate::expr::NonAggregate: $crate::expr::CombineAggr<Rhs::Aggr, Rhs::Scope>,
            (): $crate::expr::MergeDialect<Rhs::Dialect>,
        {
            type Output = $crate::expr::Expr<
                <$column as $crate::schema::Column>::RustType,
                $crate::expr::Merged<$scope, Rhs::Scope>,
                $crate::expr::CombinedAggr<$crate::expr::NonAggregate, Rhs::Aggr, Rhs::Scope>,
                $crate::expr::MergedDialect<(), Rhs::Dialect>,
            >;

            fn div(self, rhs: Rhs) -> Self::Output {
                $crate::expr::Expr::from_kind($crate::schema::arithmetic_kind(
                    $crate::expr::BinaryOp::Div,
                    <$column as $crate::schema::Column>::expr_kind(),
                    <Rhs as $crate::schema::ColumnArithmetic<$column>>::into_operand_kind(rhs),
                ))
            }
        }

        impl<Rhs $($extra_generics)*> ::core::ops::Rem<Rhs> for $column
        where
            $($extra_bounds)*
            Rhs: $crate::schema::ColumnArithmetic<$column>,
            $scope: $crate::expr::MergeScope<Rhs::Scope>,
            $crate::expr::NonAggregate: $crate::expr::CombineAggr<Rhs::Aggr, Rhs::Scope>,
            (): $crate::expr::MergeDialect<Rhs::Dialect>,
        {
            type Output = $crate::expr::Expr<
                <$column as $crate::schema::Column>::RustType,
                $crate::expr::Merged<$scope, Rhs::Scope>,
                $crate::expr::CombinedAggr<$crate::expr::NonAggregate, Rhs::Aggr, Rhs::Scope>,
                $crate::expr::MergedDialect<(), Rhs::Dialect>,
            >;

            fn rem(self, rhs: Rhs) -> Self::Output {
                $crate::expr::Expr::from_kind($crate::schema::arithmetic_kind(
                    $crate::expr::BinaryOp::Rem,
                    <$column as $crate::schema::Column>::expr_kind(),
                    <Rhs as $crate::schema::ColumnArithmetic<$column>>::into_operand_kind(rhs),
                ))
            }
        }
    };
}

// An aliased column keeps the Rust type of the column it addresses, so it takes
// part in arithmetic exactly like the plain marker does, and its expression
// stays qualified by the alias. The invocation follows the helper definition so
// that the macro is in scope wherever the aliased marker is used.
__rurqe_column_arithmetic!(
    [, A, C]
    [A: TableAlias, C: Column,]
    AliasedCol<A, C>,
    Aliased<C::Table, A>
);

/// Declares a table marker type together with its column marker types.
///
/// Each column links back to the table through [`Column::Table`] and carries its
/// Rust value type through [`Column::RustType`]:
///
/// ```
/// rurqe_core::table! {
///     /// The `users` table.
///     User => "users" {
///         UserId => "id": i64,
///         UserEmail => "email": String,
///     }
/// }
///
/// use rurqe_core::schema::{Column, Table};
///
/// assert_eq!(User::NAME, "users");
/// assert_eq!(UserEmail::NAME, "email");
/// assert_eq!(<<UserEmail as Column>::Table as Table>::NAME, "users");
/// ```
#[macro_export]
macro_rules! table {
    (
        $(#[$table_meta:meta])*
        $table:ident => $table_name:literal {
            $(
                $(#[$column_meta:meta])*
                $column:ident => $column_name:literal : $rust_type:ty,
            )*
        }
    ) => {
        $(#[$table_meta])*
        #[allow(dead_code)]
        #[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
        pub struct $table;

        impl $crate::schema::Table for $table {
            const NAME: &'static str = $table_name;
        }

        $(
            $(#[$column_meta])*
            #[allow(dead_code)]
            #[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
            pub struct $column;

            impl $crate::schema::Column for $column {
                type Table = $table;
                type RustType = $rust_type;

                const NAME: &'static str = $column_name;
            }

            $crate::__rurqe_column_arithmetic!([] [] $column, $table);
        )*
    };
}

#[cfg(test)]
mod tests {
    use super::*;

    crate::table! {
        User => "users" {
            UserId => "id": i64,
            UserEmail => "email": String,
        }
    }

    #[test]
    fn names_are_static_strings() {
        assert_eq!(User::NAME, "users");
        assert_eq!(UserId::NAME, "id");
        assert_eq!(UserEmail::NAME, "email");
    }

    #[test]
    fn column_links_to_its_table_and_rust_type() {
        assert_eq!(<<UserId as Column>::Table as Table>::NAME, "users");

        fn takes_rust_type<C: Column<RustType = String>>() {}
        takes_rust_type::<UserEmail>();
    }

    #[test]
    fn column_belongs_to_its_own_table() {
        fn assert_belongs<C: Column + ColumnBelongsTo<T>, T: Table>() {}

        assert_belongs::<UserId, User>();
        assert_belongs::<UserEmail, User>();
    }

    #[test]
    fn table_is_in_its_own_scope() {
        fn assert_in_scope<T: Table + TableInScope<T>>() {}

        assert_in_scope::<User>();
    }

    crate::table! {
        Order => "orders" {
            OrderId => "id": i64,
            OrderUserId => "user_id": i64,
        }
    }

    #[test]
    fn composite_scope_contains_all_member_tables() {
        fn assert_in_scope<T: Table, S: TableInScope<T, P>, P>() {}

        assert_in_scope::<User, (User, Order), _>();
        assert_in_scope::<Order, (User, Order), _>();
        assert_in_scope::<User, (Order, User), _>();
        assert_in_scope::<Order, (Order, User), _>();
    }

    #[test]
    fn composite_scope_supports_self_joins() {
        fn assert_in_scope<T: Table, S: TableInScope<T, P>, P>() {}

        assert_in_scope::<User, (User, User), At<1>>();
        assert_in_scope::<User, (User, User), At<2>>();
    }

    #[test]
    fn next_marker_nests_positions_without_arithmetic() {
        // `Next` wraps a position one level deeper and stays zero-sized.
        let _: Next<At<0>> = Next(core::marker::PhantomData);
        let _: Next<Next<At<0>>> = Next(core::marker::PhantomData);

        assert_eq!(core::mem::size_of::<Next<At<0>>>(), 0);
        assert_eq!(core::mem::size_of::<Next<Next<At<0>>>>(), 0);
    }

    crate::table_alias! {
        /// The `u` alias.
        UserAlias => "u"
    }

    #[test]
    fn table_reference_carries_an_optional_alias() {
        assert_eq!(User::table_ref(), TableRef::plain("users"));
        assert_eq!(
            Aliased::<User, UserAlias>::table_ref(),
            TableRef::aliased("users", "u")
        );
        assert_eq!(<Aliased<User, UserAlias> as Table>::NAME, "users");
        assert_eq!(<UserAlias as TableAlias>::NAME, "u");
    }

    #[test]
    fn aliased_column_keeps_its_type_and_qualifies_its_reference() {
        assert_eq!(<AliasedCol<UserAlias, UserId> as Column>::NAME, "id");
        assert_eq!(
            <<AliasedCol<UserAlias, UserId> as Column>::Table as Table>::NAME,
            "users"
        );
        assert_eq!(
            AliasedCol::<UserAlias, UserId>::expr_kind(),
            crate::expr::ExprKind::QualifiedColumn {
                table: "u",
                column: "id",
            }
        );
    }

    #[test]
    fn aliased_column_preserves_the_column_rust_type() {
        fn takes_rust_type<C: Column<RustType = String>>() {}

        takes_rust_type::<AliasedCol<UserAlias, UserEmail>>();
    }

    #[test]
    fn alias_helpers_produce_aliased_column_markers() {
        let through_column: AliasedCol<UserAlias, UserId> = UserId.alias::<UserAlias>();
        let through_alias: AliasedCol<UserAlias, UserId> = UserAlias.col(UserId);
        let _ = (through_column, through_alias);

        assert_eq!(<AliasedCol<UserAlias, UserId> as Column>::NAME, "id");
        assert_eq!(
            <AliasedCol<UserAlias, UserId> as Column>::expr_kind(),
            crate::expr::ExprKind::QualifiedColumn {
                table: "u",
                column: "id",
            }
        );
    }

    #[test]
    fn plain_column_expression_carries_its_owning_table() {
        assert_eq!(
            UserId::expr_kind(),
            crate::expr::ExprKind::Column {
                table: "users",
                name: "id",
            }
        );
    }

    #[test]
    fn column_markers_compose_arithmetic_expressions() {
        use crate::expr::{BinaryOp, Expr, ExprKind};

        fn op_of<T, S, A, D>(expr: &Expr<T, S, A, D>) -> BinaryOp {
            match expr.kind() {
                ExprKind::Binary { op, .. } => *op,
                other => panic!("expected an arithmetic expression, got {other:?}"),
            }
        }

        assert_eq!(op_of(&(UserId + 1i64)), BinaryOp::Add);
        assert_eq!(op_of(&(UserId - 2i64)), BinaryOp::Sub);
        assert_eq!(op_of(&(UserId * 3i64)), BinaryOp::Mul);
        assert_eq!(op_of(&(UserId / 4i64)), BinaryOp::Div);
        assert_eq!(op_of(&(UserId % 5i64)), BinaryOp::Rem);
    }

    #[test]
    fn column_markers_compose_arithmetic_with_other_columns() {
        use crate::expr::{BinaryOp, ExprKind, SqlVal};

        let total = OrderUserId + OrderId;

        assert_eq!(
            total.kind(),
            &ExprKind::Binary {
                op: BinaryOp::Add,
                lhs: Box::new(ExprKind::Column {
                    table: "orders",
                    name: "user_id",
                }),
                rhs: Box::new(ExprKind::Column {
                    table: "orders",
                    name: "id",
                }),
            }
        );

        // The scope of the produced expression carries the tables of both
        // columns, so a statement that does not select from `orders` rejects it.
        let _: crate::expr::Expr<i64, (Order, Order)> = total;

        let offset = OrderId + 1i64;
        assert_eq!(
            offset.kind(),
            &ExprKind::Binary {
                op: BinaryOp::Add,
                lhs: Box::new(ExprKind::Column {
                    table: "orders",
                    name: "id",
                }),
                rhs: Box::new(ExprKind::Value(SqlVal::I64(1))),
            }
        );
    }

    #[test]
    fn aliased_column_markers_compose_arithmetic_expressions() {
        use crate::expr::{BinaryOp, ExprKind, SqlVal};

        let scaled = AliasedCol::<UserAlias, UserId>::new() * 2i64;

        assert_eq!(
            scaled.kind(),
            &ExprKind::Binary {
                op: BinaryOp::Mul,
                lhs: Box::new(ExprKind::QualifiedColumn {
                    table: "u",
                    column: "id",
                }),
                rhs: Box::new(ExprKind::Value(SqlVal::I64(2))),
            }
        );
    }

    #[cfg(feature = "decimal")]
    mod decimal_arithmetic {
        use crate::expr::{BinaryOp, ExprKind};

        crate::table! {
            Price => "prices" {
                PriceAmount => "amount": rust_decimal::Decimal,
            }
        }

        #[test]
        fn decimal_columns_compose_arithmetic_expressions() {
            let amount = rust_decimal::Decimal::new(5, 2);

            let total = PriceAmount + amount;
            assert!(matches!(
                total.kind(),
                ExprKind::Binary {
                    op: BinaryOp::Add,
                    ..
                }
            ));

            let borrowed = &amount;
            let adjusted = PriceAmount - borrowed;
            assert!(matches!(
                adjusted.kind(),
                ExprKind::Binary {
                    op: BinaryOp::Sub,
                    ..
                }
            ));
        }
    }

    #[test]
    fn extend_scope_combines_tables_into_tuples() {
        fn assert_extend<T: ExtendScope<S, Output = Expected>, S: Table, Expected>() {}

        assert_extend::<User, Order, (User, Order)>();
        assert_extend::<(User, Order), User, (User, Order, User)>();
    }

    fn assert_expr_in_scope<S: ExprInScope<Tables, P>, Tables, P>() {}

    #[test]
    fn expressions_referencing_no_table_are_in_every_scope() {
        assert_expr_in_scope::<(), User, At<0>>();
        assert_expr_in_scope::<(), (User, Order), (At<0>, At<1>)>();
        assert_expr_in_scope::<(), User, (At<0>,)>();
    }

    #[test]
    fn expressions_referencing_a_table_follow_the_query_scope() {
        assert_expr_in_scope::<User, User, _>();
        assert_expr_in_scope::<User, (User, Order), _>();
        assert_expr_in_scope::<Order, (User, Order), _>();
        assert_expr_in_scope::<Order, (Order, User), _>();
    }

    #[test]
    fn expressions_referencing_several_tables_follow_the_query_scope() {
        assert_expr_in_scope::<(User,), User, _>();
        assert_expr_in_scope::<(User, Order), (User, Order), _>();
        assert_expr_in_scope::<(Order, User), (Order, User), _>();
        // A self-join reaches the same table through both positions, so the
        // positions must be pinned instead of inferred.
        assert_expr_in_scope::<(User, User), (User, User), (At<1>, At<2>)>();
    }

    fn assert_combined<A: CombineScope<B, Combined = C>, B, C>() {}

    #[test]
    fn combining_scopes_names_the_referenced_tables() {
        assert_combined::<(), (), ()>();
        assert_combined::<(), User, User>();
        assert_combined::<User, (), User>();
        assert_combined::<User, Order, (User, Order)>();
        assert_combined::<(User, Order), User, (User, Order, User)>();
        assert_combined::<(User, Order, User), Order, (User, Order, User, Order)>();
        assert_combined::<(User, User, User), User, (User, User, User, User)>();
    }

    #[test]
    fn a_combined_scope_is_checked_against_the_query_scope() {
        fn require_combined_in_scope<A, B, Tables, P>()
        where
            A: CombineScope<B>,
            <A as CombineScope<B>>::Combined: ExprInScope<Tables, P>,
        {
        }

        require_combined_in_scope::<(), User, User, _>();
        require_combined_in_scope::<User, Order, (User, Order), _>();
    }
}
